const AP = {
  VIDP:[28.5665,77.1031], VABB:[19.0887,72.8679], VOBL:[13.1979,77.7063], VOMM:[12.99,80.1693],
  VECC:[22.6547,88.4467], VOHS:[17.2403,78.4294], VAAH:[23.0772,72.6347], VOCI:[10.152,76.4019],
  VAPO:[18.5821,73.9197], VOGO:[15.3808,73.8314], VILK:[26.7606,80.8893], VIJP:[26.8242,75.8122],
  VEPT:[25.5913,85.088], VEGT:[26.1061,91.5859], VOTV:[8.4821,76.9201], VIAR:[31.7096,74.7973],
  VANP:[21.0922,79.0472], VAID:[22.7218,75.8011], OMDB:[25.2528,55.3644], OTHH:[25.2731,51.6081],
  WSSS:[1.3644,103.9915], EGLL:[51.47,-0.4543], EDDF:[50.0379,8.5622], VTBS:[13.69,100.7501]
};

const all = $input.all();
const list = (all.length === 1 && Array.isArray(all[0].json.data))
  ? all[0].json.data
  : all.map(i => i.json);

const q = $('Webhook').first().json.query || {};
const flightId = (q.flight || '').toUpperCase();
const role = (q.role || (flightId ? 'passenger' : 'home')).toLowerCase();

const found = role === 'home'
  ? null
  : (list.find(x => x.flight_no === flightId) || list.find(x => x.flight_no === 'AI101'));
const flight = found
  ? { ...found, from_lat: (AP[found.from_icao] || [])[0], from_lon: (AP[found.from_icao] || [])[1] }
  : null;

const sample = list.slice(0, 15).map(x => ({
  flight_no: x.flight_no, from_iata: x.from_iata, to_iata: x.to_iata,
  departure_time: x.departure_time, status: x.status, delay_min: x.delay_min
}));

const sameAirport = flight
  ? list.filter(x => x.from_icao === flight.from_icao && x.flight_no !== flight.flight_no)
        .sort((a, b) => a.departure_time.localeCompare(b.departure_time))
        .slice(0, 8)
        .map(x => ({ flight_no: x.flight_no, to_iata: x.to_iata, gate: x.gate,
                     departure_time: x.departure_time, status: x.status, delay_min: x.delay_min }))
  : [];

return [{ json: { role, flight, sample, sameAirport, total: list.length } }];

const d = $('Passenger Data').first().json;
const wxAll = $('Weather').all().map(i => i.json);
const traffic = ($input.first() && $input.first().json) || {};
const f = d.flight;
const role = d.role;
const P = 'flight-status';

const css = `
*{box-sizing:border-box}
body{font-family:Arial,sans-serif;background:#0b1f3a;color:#fff;margin:0;padding:16px;max-width:980px;margin:auto}
.card{background:#12305a;border-radius:12px;padding:16px;margin-bottom:12px}
h1{margin:0 0 4px}h2{margin:0 0 10px;font-size:18px;color:#9fd3ff}
.big{font-size:30px;font-weight:bold}
.pill{display:inline-block;padding:4px 12px;border-radius:20px;font-weight:bold;color:#fff}
.nav{font-size:13px;margin-bottom:12px}.nav a{color:#9fd3ff;margin-right:10px}
a{color:#9fd3ff}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.kpi{background:#0e2748;border-radius:10px;padding:12px;text-align:center}
.kpi b{display:block;font-size:22px}
.kpi span{font-size:12px;color:#9fb6d3}
table{width:100%;border-collapse:collapse;font-size:13px}
th,td{text-align:left;padding:6px 8px;border-bottom:1px solid #1f4378}
th{color:#9fd3ff}
.bar{background:#0e2748;border-radius:10px;height:18px;overflow:hidden}
.bar div{background:#27ae60;height:100%}
.banner{border-radius:12px;padding:14px;margin-bottom:12px;font-weight:bold;font-size:16px}
.ok{background:#1e8449}.warn{background:#c0392b}.mid{background:#d68910}
.tag{font-size:11px;color:#9fb6d3}
input,button{font-size:16px;padding:10px 14px;border-radius:8px;border:0;margin:4px 4px 4px 0}
button{background:#2e86de;color:#fff;font-weight:bold;cursor:pointer}
ul{list-style:none;padding:0;margin:0}li{padding:3px 0}
`;
const page = (title, body) => `<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="60"><title>${title}</title><style>${css}</style></head><body>${body}</body></html>`;

// ---------------- HOME ----------------
if (role === 'home' || !f) {
  const rows = d.sample.map(s => `<tr><td><b>${s.flight_no}</b></td><td>${s.from_iata} → ${s.to_iata}</td>
<td>${s.departure_time}</td><td>${s.delay_min > 0 ? 'Delayed ' + s.delay_min + ' min' : s.status}</td>
<td><a href="${P}?role=pilot&amp;flight=${s.flight_no}">Pilot</a> · <a href="${P}?role=ground&amp;flight=${s.flight_no}">Ground</a> · <a href="${P}?role=passenger&amp;flight=${s.flight_no}">Passenger</a></td></tr>`).join('');
  const body = `
<div class="card"><h1>✈️ Airline Operations Portal</h1>
<div class="tag">${d.total} flights loaded · demo data · live weather from aviationweather.gov</div></div>
<div class="card"><h2>Open a flight</h2>
<form action="${P}" method="get">
<input name="flight" value="AI101" placeholder="Flight e.g. AI101" required>
<button name="role" value="pilot">👨‍✈️ Pilot</button>
<button name="role" value="ground">🧳 Ground staff</button>
<button name="role" value="passenger">🧍 Passenger</button>
</form></div>
<div class="card"><h2>Sample flights</h2>
<table><tr><th>Flight</th><th>Route</th><th>Dep</th><th>Status</th><th>Open as</th></tr>${rows}</table></div>`;
  return [{ json: { html: page('Airline Operations Portal', body) } }];
}

// ---------------- shared calculations ----------------
const wx = icao => wxAll.find(w => w.icaoId === icao) || {};
const dep = wx(f.from_icao), arr = wx(f.to_icao);
const risky = w => ['IFR', 'LIFR'].includes(w.fltCat) || (w.wspd || 0) > 25;
const catColor = w => risky(w) ? '#ff6b5b' : '#5fe08f';

const nowStr = new Date().toLocaleTimeString('en-GB', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit' });
const mins = t => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
const now = mins(nowStr), b = mins(f.boarding_time), dp = mins(f.departure_time);
let phase, pct;
if (now < b - 60) { phase = 'Check-in open'; pct = 0; }
else if (now < b) { phase = 'Boarding opens soon'; pct = 0; }
else if (now < dp - 15) { phase = 'Boarding'; pct = Math.round((now - b) / ((dp - 15) - b) * 100); }
else if (now < dp) { phase = 'Gate closing'; pct = 100; }
else { phase = 'Departed'; pct = 100; }
const delayed = Number(f.delay_min) > 0;
const statusText = delayed ? `Delayed ${f.delay_min} min · ${phase}` : phase;
const statusColor = delayed ? '#e67e22' : (phase === 'Gate closing' ? '#c0392b' : '#27ae60');

const pax = d.pax || [];
const nBiz = pax.filter(p => p.cabin === 'Business').length;
const nEco = pax.length - nBiz;
const bagKg = pax.reduce((s, p) => s + Number(p.baggage_kg || 0), 0);
const special = pax.filter(p => !['Vegetarian', 'Non-vegetarian', 'No meal'].includes(p.meal)).length;

const nav = `<div class="nav"><a href="${P}?role=home">🏠 Home</a>
<a href="${P}?role=pilot&amp;flight=${f.flight_no}">Pilot</a>
<a href="${P}?role=ground&amp;flight=${f.flight_no}">Ground staff</a>
<a href="${P}?role=passenger&amp;flight=${f.flight_no}">Passenger</a></div>`;

const head = (label) => `${nav}
<div class="card"><div class="tag">${label} · ${f.airline} · Live time (IST) ${nowStr}</div>
<h1>✈️ ${f.flight_no}</h1>
<div class="big">${f.from_iata} → ${f.to_iata}</div>
<div>${f.from_city} to ${f.to_city}</div><br>
<span class="pill" style="background:${statusColor}">${statusText}</span>
<p>Terminal <b>${f.terminal}</b> | Gate <b>${f.gate}</b></p>
<p>Boarding <b>${f.boarding_time}</b> | Departure <b>${f.departure_time}</b> | Arrival <b>${f.arrival_time}</b></p>
<div class="bar"><div style="width:${pct}%"></div></div>
<div class="tag">Boarding progress ${pct}%</div></div>`;

const wxCard = (title, icao, w) => `<div class="card"><h2>${title} (${icao})</h2>
<div>Conditions: <b style="color:${catColor(w)}">${w.fltCat || 'N/A'}</b></div>
<div>Temperature: ${w.temp ?? 'N/A'} °C · Wind: ${w.wspd ?? 'N/A'} kt · Visibility: ${w.visib ?? 'N/A'}</div>
${w.rawOb ? `<div class="tag" style="margin-top:6px">${w.rawOb}</div>` : ''}</div>`;


// ---------------- live traffic radar (adsb.lol) ----------------
const R = 40; // nautical miles
const trafficList = (f.from_lat == null) ? [] : (Array.isArray(traffic.ac) ? traffic.ac : [])
  .filter(a => typeof a.lat === 'number' && typeof a.lon === 'number')
  .map(a => {
    const dx = (a.lon - f.from_lon) * Math.cos(f.from_lat * Math.PI / 180) * 60;
    const dy = (a.lat - f.from_lat) * 60;
    return { ...a, dx, dy, dist: Math.sqrt(dx * dx + dy * dy) };
  })
  .filter(a => a.dist <= R)
  .sort((a, b) => a.dist - b.dist);
const csign = a => ((a.flight || '').trim() || (a.r || '') || a.hex || '?');
const altTxt = a => typeof a.alt_baro === 'number' ? Math.round(a.alt_baro) + ' ft' : 'on ground';
const SC = 150 / R;
const dots = trafficList.slice(0, 60).map((a, i) => {
  const x = (160 + a.dx * SC).toFixed(1), y = (160 - a.dy * SC).toFixed(1);
  return `<polygon points="0,-6 4,5 -4,5" transform="translate(${x} ${y}) rotate(${a.track || 0})" fill="#ffd166"/>`
    + (i < 6 ? `<text x="${(+x + 7).toFixed(1)}" y="${(+y + 3).toFixed(1)}" font-size="9" fill="#cfe3ff">${csign(a)}</text>` : '');
}).join('');
const svg = `<svg viewBox="0 0 320 320" style="width:100%;max-width:360px;background:#0a1a30;border-radius:12px">
<circle cx="160" cy="160" r="150" fill="none" stroke="#1f4378"/><circle cx="160" cy="160" r="75" fill="none" stroke="#1f4378"/>
<line x1="10" y1="160" x2="310" y2="160" stroke="#1f4378"/><line x1="160" y1="10" x2="160" y2="310" stroke="#1f4378"/>
<text x="165" y="86" font-size="9" fill="#6b8cb8">${R / 2} nm</text><text x="165" y="22" font-size="9" fill="#6b8cb8">${R} nm</text>
${dots}<circle cx="160" cy="160" r="5" fill="#5fe08f"/><text x="168" y="176" font-size="11" fill="#5fe08f" font-weight="bold">${f.from_iata}</text></svg>`;
const frLink = f.from_lat == null ? '#' : `https://www.flightradar24.com/${f.from_lat.toFixed(2)},${f.from_lon.toFixed(2)}/10`;
const trafficCard = showTable => `<div class="card"><h2>Live air traffic near ${f.from_iata}</h2>
${Array.isArray(traffic.ac)
  ? `<div class="tag" style="margin-bottom:8px">${trafficList.length} aircraft within ${R} nm right now (real ADS-B data)</div>${svg}`
  : `<div>Live traffic data is not available right now.</div>`}
${showTable && trafficList.length ? `<table style="margin-top:8px"><tr><th>Callsign</th><th>Type</th><th>Altitude</th><th>Speed</th><th>Distance</th></tr>${
  trafficList.slice(0, 8).map(a => `<tr><td>${csign(a)}</td><td>${a.t || '-'}</td><td>${altTxt(a)}</td><td>${Math.round(a.gs || 0)} kt</td><td>${a.dist.toFixed(0)} nm</td></tr>`).join('')}</table>` : ''}
<div class="tag" style="margin-top:8px">Source: adsb.lol community network · <a href="${frLink}" target="_blank" rel="noopener">Open this area on Flightradar24</a></div></div>`;

let body = '';

// ---------------- PILOT ----------------
if (role === 'pilot') {
  const anyRisk = risky(dep) || risky(arr);
  const banner = anyRisk
    ? `<div class="banner warn">⚠️ CAUTION: adverse weather at ${risky(dep) ? f.from_icao : ''} ${risky(arr) ? f.to_icao : ''}. Review before departure.</div>`
    : `<div class="banner ok">✅ GO: weather within limits at departure and destination</div>`;
  const checks = [['Flight plan filed', true], ['Fuel uplift and reserves', true], ['Weight and balance', true],
    ['NOTAMs reviewed', true], ['Engines and hydraulics', true], ['Flight controls', true],
    ['Navigation systems', true], ['Weather review', !anyRisk]];
  const checkRows = checks.map(c => `<tr><td>${c[0]}</td><td>${c[1] ? '✅ Complete' : '⚠️ Review'}</td></tr>`).join('');
  body = head('PILOT BRIEFING') + banner + `
<div class="card"><h2>Flight</h2><div class="grid">
<div class="kpi"><b>${f.aircraft}</b><span>Aircraft</span></div>
<div class="kpi"><b>${f.distance_km} km</b><span>Distance</span></div>
<div class="kpi"><b>${f.duration_min} min</b><span>Block time</span></div>
<div class="kpi"><b>${pax.length}</b><span>Passengers booked</span></div></div>
<p>Captain: <b>${f.pilot}</b><br>First officer: <b>${f.copilot}</b></p>
<div class="tag">Cabin: ${nBiz} business, ${nEco} economy · Baggage ${bagKg} kg · ${special} special meals</div></div>
${wxCard('Departure weather', f.from_icao, dep)}${wxCard('Destination weather', f.to_icao, arr)}
${trafficCard(true)}
<div class="card"><h2>Pre-flight checklist</h2><table>${checkRows}</table></div>`;
}

// ---------------- GROUND STAFF ----------------
else if (role === 'ground') {
  const alert = (risky(dep) || delayed)
    ? `<div class="banner warn">⚠️ DELAY RISK: ${delayed ? 'flight delayed ' + f.delay_min + ' min. ' : ''}${risky(dep) ? 'Weather at ' + f.from_icao + ' is ' + (dep.fltCat || 'poor') + '. ' : ''}Alert gates, crew and passenger services.</div>`
    : `<div class="banner ok">✅ NORMAL OPERATIONS</div>`;
  const manifest = pax.map(p => `<tr><td>${p.boarding_seq}</td><td>${p.title} ${p.first_name} ${p.last_name}</td><td>${p.seat}</td><td>${p.cabin}</td><td>${p.boarding_group}</td><td>${p.pnr}</td><td>${p.baggage_kg} kg</td><td>${p.meal}</td></tr>`).join('');
  const others = (d.sameAirport || []).map(o => `<tr><td><a href="${P}?role=ground&amp;flight=${o.flight_no}">${o.flight_no}</a></td><td>→ ${o.to_iata}</td><td>${o.gate}</td><td>${o.departure_time}</td><td>${o.delay_min > 0 ? 'Delayed ' + o.delay_min + ' min' : o.status}</td></tr>`).join('');
  body = head('GROUND STAFF DASHBOARD') + alert + `
<div class="card"><h2>Load summary</h2><div class="grid">
<div class="kpi"><b>${pax.length}</b><span>Passengers</span></div>
<div class="kpi"><b>${nBiz} / ${nEco}</b><span>Business / Economy</span></div>
<div class="kpi"><b>${bagKg} kg</b><span>Checked baggage</span></div>
<div class="kpi"><b>${special}</b><span>Special meals</span></div></div></div>
${wxCard('Weather at departure', f.from_icao, dep)}
${trafficCard(true)}
<div class="card"><h2>Passenger manifest</h2><table>
<tr><th>#</th><th>Name</th><th>Seat</th><th>Cabin</th><th>Grp</th><th>PNR</th><th>Bags</th><th>Meal</th></tr>${manifest}</table></div>
<div class="card"><h2>Other departures from ${f.from_iata}</h2><table>
<tr><th>Flight</th><th>To</th><th>Gate</th><th>Dep</th><th>Status</th></tr>${others}</table></div>`;
}

// ---------------- PASSENGER ----------------
else {
  const checks = ['Engines', 'Fuel', 'Flight controls', 'Cabin safety equipment', 'Navigation systems'];
  const items = checks.map(c => `<li>✅ ${c}</li>`).join('');
  body = head('PASSENGER INFORMATION') + `
<div class="card"><h2>Your crew</h2>
<div>Pilot: <b>${f.pilot}</b></div><div>Co-pilot: <b>${f.copilot}</b></div>
<div>Aircraft: ${f.aircraft}</div></div>
<div class="card"><h2>Pre-flight checks</h2><ul>${items}</ul></div>
${wxCard('Weather at ' + f.from_city, f.from_icao, dep)}${wxCard('Weather at ' + f.to_city, f.to_icao, arr)}
${trafficCard(false)}`;
}

body += `<p class="tag">Page refreshes every minute · Demo data</p>`;
return [{ json: { html: page(f.flight_no + ' ' + role, body) } }];

const fd = $('Flight Data').first().json;

let pax = [];
if (fd.flight) {
  pax = $input.all()
    .map(i => i.json)
    .filter(p => p.flight_no === fd.flight.flight_no)
    .sort((a, b) => Number(a.boarding_seq) - Number(b.boarding_seq));
}

return [{ json: { ...fd, pax } }];
